	/**  Hostname or IP (serial: the port name, e.g. `COM3` or `/dev/ttyUSB0`). */
	hostname: string,
	/**  SSH or telnet port. */
	port: number,
	/**  Line settings (serial only). */
	serial: SerialConfig | null,
	/**  Command whose stdin/stdout carry the SSH connection (OpenSSH `ProxyCommand`). */
