/**  One transfer as the UI sees it (also the progress event). */
export type Transfer = {
	/**  Id. */
	id: string,
	/**  Direction. */
	direction: Direction,
	/**  File name. */
	name: string,
	/**  Local path. */
	local: string,
	/**  Remote path. */
	remote: string,
	/**  Host id. */
	hostId: string,
	/**  Host label. */
	hostLabel: string,
	/**  Total bytes. */
	size: number,
	/**  Bytes done. */
	done: number,
	/**  Bytes per second during this run. */
	speed: number,
	/**  Status. */
	status: TransferStatus,
	/**  Why it failed. */
	error: string | null,
};

/**  Transfer settings (S5). */
export type TransferSettings = {
	/**  Transfers at once (1–8). */
	concurrency: number,
	/**  Total speed limit in KiB/s (0 = none). */
	limitKbps: number,
};

/**  Where a transfer is. */
export type TransferStatus = 
/**  Waiting for a slot. */
"queued" | 
/**  Moving bytes. */
"running" | 
/**  Stopped by the user; resumes from where it stopped. */
"paused" | 
/**  Finished. */
"done" | 
/**  Gave up after retries. */
"failed" | 
/**  Stopped for good. */
"cancelled";

/**  The user picked a host in the tray menu. */
export type TrayConnectEvent = {
	/**  Host id. */
	hostId: string,
};

/**  A host listed under "Recent hosts" in the tray. */
